pub open spec fn pages_free_direct_is_correct(
    pfd: Seq<*mut Page>, pages: Seq<PageQueue>, emp: *mut Page,
) -> bool {
    &&& pfd.len() == PAGES_DIRECT
    &&& pages.len() == BIN_FULL + 1
